# Generated by scripts/homebrew_formula.sh in bircni/git-statuses on every release.
# Changes made here are overwritten by the next release.
class GitStatuses < Formula
  desc "Display Git repository statuses in a table format"
  homepage "https://github.com/bircni/git-statuses"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/bircni/git-statuses/releases/download/0.8.2/git-statuses-0.8.2-aarch64-apple-darwin.tar.gz"
      sha256 "ff834bd1c993835e8fc81bca622930b170fb1360ce1a0b14293f15a72faefc63"
    end
    on_intel do
      url "https://github.com/bircni/git-statuses/releases/download/0.8.2/git-statuses-0.8.2-x86_64-apple-darwin.tar.gz"
      sha256 "c83b33d0b6b4eebc4d088757159b1cb76f91d204cb1142e397ca342dc6c7273a"
    end
  end

  on_linux do
    # Only an x86_64 build is published for Linux.
    depends_on arch: :x86_64

    on_intel do
      url "https://github.com/bircni/git-statuses/releases/download/0.8.2/git-statuses-0.8.2-x86_64-unknown-linux-musl.tar.gz"
      sha256 "a42b809b4073f3abc0a6aed9ed629ef6cffc2354ecb7a6a3282712bf8c39a504"
    end
  end

  def install
    bin.install "git-statuses"
    generate_completions_from_executable(bin/"git-statuses", "--completions")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/git-statuses --version")

    (testpath/"scan").mkpath
    assert_equal '{"failed":[],"repositories":[]}',
                 shell_output("#{bin}/git-statuses --json #{testpath}/scan").strip
  end
end
